from pathlib import Path


def replace_once(path, old, new):
    p=Path(path)
    s=p.read_text(encoding='utf-8')
    if old not in s:
        raise SystemExit(f'Pattern not found in {path}: {old[:120]}')
    p.write_text(s.replace(old,new,1),encoding='utf-8')

