old_save="async function save(){const err=validate();if(err)return global.toast?.(err);const eligible=new Map(eligibleClasses().map(s=>[s.id,s])),br=branches().find(x=>x.id===draft.bransId),old=editingId?records().find(x=>x.id===editingId):null,u=user(),payload={...normalizeDraft(draft),bransAdi:draft.tur==='zumre'&&draft.kademe==='ortaokul'?String(br?.ad||draft.bransAdi||''):'',sinifAdlari:draft.tumSiniflar?[]:draft.sinifIdler.map(id=>className(eligible.get(id))).filter(Boolean),konu:draft.konu.trim(),olusturanUid:old?.olusturanUid||u.uid||'',olusturanAdi:old?.olusturanAdi||currentName(),olusturmaTarihi:old?.olusturmaTarihi||new Date().toISOString(),guncellenmeTarihi:new Date().toISOString()};try{await Service.kaydet(editingId||null,payload);const keep=draft.kademe;editingId='';draft=blankDraft(keep);global.toast?.('Toplantı çizelgesine kaydedildi.');render()}catch(e){global.toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Toplantı kaydedilemedi: '+(e?.message||e))}}"
new_save="async function save({keepReady=false}={}){const err=validate();if(err){formMessage=err;render();global.toast?.(err);return false}formMessage='';const eligible=new Map(eligibleClasses().map(s=>[s.id,s])),br=branches().find(x=>x.id===draft.bransId),old=editingId?records().find(x=>x.id===editingId):null,u=user(),payload={...normalizeDraft(draft),bransAdi:draft.tur==='zumre'&&draft.kademe==='ortaokul'?String(br?.ad||draft.bransAdi||''):'',sinifAdlari:draft.tumSiniflar?[]:draft.sinifIdler.map(id=>className(eligible.get(id))).filter(Boolean),konu:draft.konu.trim(),olusturanUid:old?.olusturanUid||u.uid||'',olusturanAdi:old?.olusturanAdi||currentName(),olusturmaTarihi:old?.olusturmaTarihi||new Date().toISOString(),guncellenmeTarihi:new Date().toISOString()};try{await Service.kaydet(editingId||null,payload);const keep=draft.kademe;editingId='';draft=blankDraft(keep);global.toast?.(keepReady?'Satır eklendi. Yeni toplantıyı girebilirsiniz.':'Toplantı çizelgesine kaydedildi.');render();return true}catch(e){const msg=e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Toplantı kaydedilemedi: '+(e?.message||e);formMessage=msg;render();global.toast?.(msg);return false}}"
