old_bind="function bind(){if(!root)return;root.querySelectorAll('[data-meeting-kademe]').forEach(b=>b.onclick=()=>setKademe(b.dataset.meetingKademe));root.querySelectorAll('[data-meeting-type]').forEach(b=>b.onclick=()=>setType(b.dataset.meetingType));root.querySelectorAll('[data-meeting-level]').forEach(b=>b.onclick=()=>toggleLevel(b.dataset.meetingLevel));root.querySelector('[data-meeting-branch]')?.addEventListener('change',e=>{draft.bransId=e.target.value;draft.bransAdi=branches().find(x=>x.id===draft.bransId)?.ad||''});root.querySelector('[data-meeting-all-classes]')?.addEventListener('click',()=>{draft.tumSiniflar=!draft.tumSiniflar;if(draft.tumSiniflar)draft.sinifIdler=[];render()});root.querySelectorAll('[data-meeting-class]').forEach(b=>b.onclick=()=>toggleClass(b.dataset.meetingClass));root.querySelector('[data-meeting-date]')?.addEventListener('change',e=>{draft.tarih=e.target.value});root.querySelector('[data-meeting-time]')?.addEventListener('change',e=>{draft.saat=e.target.value});root.querySelector('[data-meeting-topic]')?.addEventListener('input',e=>{draft.konu=e.target.value});root.querySelector('[data-meeting-new]')?.addEventListener('click',()=>{const keep=draft.kademe;editingId='';draft=blankDraft(keep);render()});root.querySelector('[data-meeting-save]')?.addEventListener('click',save);root.querySelectorAll('[data-meeting-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.meetingEdit));root.querySelectorAll('[data-meeting-delete]').forEach(b=>b.onclick=()=>remove(b.dataset.meetingDelete));root.querySelector('[data-meeting-report]')?.addEventListener('click',printReport);global.PermissionService?.apply?.(root)}"
new_bind="function handleClick(e){const el=e.target?.closest?.('button');if(!el||!root?.contains(el))return;if(el.hasAttribute('data-meeting-kademe'))return setKademe(el.dataset.meetingKademe);if(el.hasAttribute('data-meeting-type'))return setType(el.dataset.meetingType);if(el.hasAttribute('data-meeting-level'))return toggleLevel(el.dataset.meetingLevel);if(el.hasAttribute('data-meeting-all-classes')){clearFormMessage();draft.tumSiniflar=!draft.tumSiniflar;if(draft.tumSiniflar)draft.sinifIdler=[];render();return}if(el.hasAttribute('data-meeting-class'))return toggleClass(el.dataset.meetingClass);if(el.hasAttribute('data-meeting-new')){if(editingId){const keep=draft.kademe;editingId='';draft=blankDraft(keep);clearFormMessage();render();return}void save({keepReady:true});return}if(el.hasAttribute('data-meeting-save')){void save();return}if(el.hasAttribute('data-meeting-edit'))return edit(el.dataset.meetingEdit);if(el.hasAttribute('data-meeting-delete')){void remove(el.dataset.meetingDelete);return}if(el.hasAttribute('data-meeting-report'))void printReport()}\nfunction handleChange(e){const el=e.target;if(!el||!root?.contains(el))return;if(el.matches?.('[data-meeting-branch]')){clearFormMessage();draft.bransId=el.value;draft.bransAdi=branches().find(x=>x.id===draft.bransId)?.ad||'';return}if(el.matches?.('[data-meeting-date]')){clearFormMessage();draft.tarih=el.value;return}if(el.matches?.('[data-meeting-time]')){clearFormMessage();draft.saat=el.value}}\nfunction handleInput(e){const el=e.target;if(el?.matches?.('[data-meeting-topic]')){clearFormMessage();draft.konu=el.value}}\nfunction bind(){if(!root)return;root.onclick=handleClick;root.onchange=handleChange;root.oninput=handleInput;global.PermissionService?.apply?.(root)}"
